package web

import (
	"embed"
	"io/fs"
	"log/slog"
	"net/http"
	"path"
	"strings"

	"github.com/gin-gonic/gin"
	"go.uber.org/fx"
)

// Dist contains the production frontend generated by `npm run build`.
// The checked-in .keep file lets backend-only Go tooling compile before that build.
//
//go:embed all:dist
var Dist embed.FS

var Module = fx.Module("web", fx.Invoke(register))

func register(router *gin.Engine) {
	assets, err := fs.Sub(Dist, "dist")
	if err != nil {
		slog.Error("open embedded frontend", "error", err)
		router.NoRoute(frontendUnavailable)
		return
	}
	if _, err := fs.Stat(assets, "index.html"); err != nil {
		slog.Warn("embedded frontend is missing; run `npm run build` in frontend", "error", err)
	}
	router.NoRoute(Handler(assets))
}

// Handler serves embedded files and falls back to index.html for Vue Router paths.
// It accepts an fs.FS so the routing behavior can be tested without a frontend build.
func Handler(assets fs.FS) gin.HandlerFunc {
	index, indexErr := fs.ReadFile(assets, "index.html")
	fileServer := http.FileServer(http.FS(assets))
	return func(c *gin.Context) {
		requestPath := path.Clean("/" + c.Request.URL.Path)
		if requestPath == "/api" || strings.HasPrefix(requestPath, "/api/") {
			c.JSON(http.StatusNotFound, gin.H{"error": "not found"})
			return
		}
		if c.Request.Method != http.MethodGet && c.Request.Method != http.MethodHead {
			c.Status(http.StatusNotFound)
			return
		}

		name := strings.TrimPrefix(requestPath, "/")
		if name == "" || name == "." {
			name = "index.html"
		}
		if _, err := fs.Stat(assets, name); err == nil {
			fileServer.ServeHTTP(c.Writer, c.Request)
			return
		}
		if path.Ext(name) != "" {
			if name == "index.html" && indexErr != nil {
				http.Error(c.Writer, "embedded frontend is unavailable; run `npm run build` in frontend", http.StatusServiceUnavailable)
				return
			}
			c.Status(http.StatusNotFound)
			return
		}
		if indexErr != nil {
			http.Error(c.Writer, "embedded frontend is unavailable; run `npm run build` in frontend", http.StatusServiceUnavailable)
			return
		}
		c.Data(http.StatusOK, "text/html; charset=utf-8", index)
	}
}

func frontendUnavailable(c *gin.Context) {
	if c.Request.URL.Path == "/api" || strings.HasPrefix(c.Request.URL.Path, "/api/") {
		c.JSON(http.StatusNotFound, gin.H{"error": "not found"})
		return
	}
	http.Error(c.Writer, "embedded frontend is unavailable", http.StatusServiceUnavailable)
}
